// Solder Wisp Enclosure - Procedural OpenSCAD
$fn = 36;
wall = 2.0;
inner_x = 108.0;
inner_y = 81.0;
inner_z = 30.0;
outer_x = inner_x + 2*wall;
outer_y = inner_y + 2*wall;
outer_z = inner_z + 2*wall;

module wisp_enclosure() {
  difference() {
    cube([outer_x, outer_y, outer_z]);
    translate([wall, wall, wall])
      cube([inner_x, inner_y, inner_z + 1]);
    // MicroUSB / Type-C cutouts
    translate([-1, 18, wall + 2])
      cube([wall + 2, 12, 8]);
    // Honeycomb air ventilation mesh for MQ-135
    for (r = [0:3]) {
      for (c = [0:4]) {
        translate([outer_x - wall - 1, 15 + (c*5), wall + 6 + (r*5)])
          cube([wall + 2, 2.5, 2.5]);
      }
    }
  }
}

module wisp_lid() {
  difference() {
    cube([outer_x, outer_y, wall + 2]);
    // OLED Bezel Window
    translate([wall + 38, wall + 38, -1])
      cube([27, 18, wall + 4]);
    // Buzzer sound aperture
    translate([wall + 16, wall + 72, -1])
      cylinder(r = 2.5, h = wall + 4);
  }
}

wisp_enclosure();
translate([0, outer_y + 12, 0]) wisp_lid();

