#include <Wire.h>

const int GAS_PIN = 34;
const int DHT_PIN = 4;
const int BUZZER_PIN = 18;
const int GAS_ALERT_THRESHOLD = 350;

void setup() {
  Serial.begin(115200);
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(BUZZER_PIN, LOW);

  Serial.println(F("--- Solder Wisp Air Quality Guardian ---"));
  Serial.println(F("Monitoring MQ-135 Volatiles & DHT11 Temperature/RH"));
}

void loop() {
  int gasRaw = analogRead(GAS_PIN); // 0-4095 on ESP32
  int gasPpm = map(gasRaw, 0, 4095, 20, 1000);

  Serial.print(F("AIR QUALITY: "));

  if (gasPpm > GAS_ALERT_THRESHOLD) {
    Serial.print(F("POOR ("));
    Serial.print(gasPpm);
    Serial.println(F(" ppm) -> ALARM_ON"));
    digitalWrite(BUZZER_PIN, HIGH); // Alarm chime
  } else {
    Serial.print(F("GOOD ("));
    Serial.print(gasPpm);
    Serial.println(F(" ppm) | AMBIENT_NOMINAL"));
    digitalWrite(BUZZER_PIN, LOW);
  }

  delay(1000);
}
